                    const unsigned char pattern4[] = {0xF3, 0x0F, 0x10, 0x8B, 0x00, 0x00, 0x00, 0x00};
                    found = reader.FindPatternEx(pattern4, "xxxx????", moduleBase, GameOffsets::PATTERN_SEARCH_SIZE);
                }

                if (found)
                {
                    // Extract offset from the instruction at [found+4]
                    // The instruction format is: F3 0F 10 [RX+offset32]
                    // Where offset32 is at bytes [4-7]
                    int32_t positionOffset = reader.Read<int32_t>(found + 4);

                    // Validate offset is reasonable (should be between 0x0 and 0x1000)
                    if (positionOffset > 0 && positionOffset < 0x1000)
