// Add this to BotEngine.cpp GetPlayerState() for debugging
// This version searches for multiple patterns and logs results

// TEMPORARY DEBUG VERSION - shows which patterns are found

PlayerState BotEngine::GetPlayerState() const
{
    PlayerState state = {0};

    try
    {
        MemoryReader reader(m_processHandle);

        // Get D2R module base
        MODULEENTRY32 me32 = {sizeof(MODULEENTRY32)};
        HANDLE hModuleSnap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE, m_processId);
        if (hModuleSnap != INVALID_HANDLE_VALUE)
        {
            uintptr_t moduleBase = 0;

            if (Module32First(hModuleSnap, &me32))
            {
                do
                {
                    if (_wcsicmp(me32.szModule, L"D2R.exe") == 0)
                    {
                        moduleBase = (uintptr_t)me32.modBaseAddr;
                        break;
                    }
                } while (Module32Next(hModuleSnap, &me32));
            }
            CloseHandle(hModuleSnap);

            if (moduleBase)
            {
                printf("[*] D2R Module Base: 0x%llX\n", moduleBase);
                printf("[*] Searching for player position patterns...\n");
                printf("[*] Search range: 0x%llX to 0x%llX\n", 
                       moduleBase, moduleBase + GameOffsets::PATTERN_SEARCH_SIZE);

                // Try multiple patterns for player position
                uintptr_t found = 0;

                // Pattern 1: EXACT from dump - F3 0F 10 87 04 01 00 00
                const unsigned char pattern1[] = {0xF3, 0x0F, 0x10, 0x87, 0x04, 0x01, 0x00, 0x00};
                found = reader.FindPatternEx(pattern1, "xxxxxxxx", moduleBase, GameOffsets::PATTERN_SEARCH_SIZE);
                printf("[*] Pattern 1 (F3 0F 10 87 04 01 00 00): %s\n", found ? "FOUND [OK]" : "NOT FOUND");
                if (found) printf("    Found at: 0x%llX\n", found);

                // Pattern 2: Wildcard offset - F3 0F 10 87 ?? ?? ?? ??
                if (!found)
                {
                    const unsigned char pattern2[] = {0xF3, 0x0F, 0x10, 0x87, 0x00, 0x00, 0x00, 0x00};
                    found = reader.FindPatternEx(pattern2, "xxxx????", moduleBase, GameOffsets::PATTERN_SEARCH_SIZE);
                    printf("[*] Pattern 2 (F3 0F 10 87 ????????): %s\n", found ? "FOUND [OK]" : "NOT FOUND");
                    if (found) printf("    Found at: 0x%llX\n", found);
                }

                // Pattern 3: F3 0F 10 83 ?? ?? ?? ??
                if (!found)
                {
                    const unsigned char pattern3[] = {0xF3, 0x0F, 0x10, 0x83, 0x00, 0x00, 0x00, 0x00};
                    found = reader.FindPatternEx(pattern3, "xxxx????", moduleBase, GameOffsets::PATTERN_SEARCH_SIZE);
                    printf("[*] Pattern 3 (F3 0F 10 83 ????????): %s\n", found ? "FOUND [OK]" : "NOT FOUND");
                    if (found) printf("    Found at: 0x%llX\n", found);
                }

                // Pattern 4: F3 0F 10 8F ?? ?? ?? ??
                if (!found)
                {
                    const unsigned char pattern4[] = {0xF3, 0x0F, 0x10, 0x8F, 0x00, 0x00, 0x00, 0x00};
                    found = reader.FindPatternEx(pattern4, "xxxx????", moduleBase, GameOffsets::PATTERN_SEARCH_SIZE);
                    printf("[*] Pattern 4 (F3 0F 10 8F ????????): %s\n", found ? "FOUND [OK]" : "NOT FOUND");
                    if (found) printf("    Found at: 0x%llX\n", found);
                }

                // Pattern 5: F3 0F 10 8B ?? ?? ?? ??
                if (!found)
                {
                    const unsigned char pattern5[] = {0xF3, 0x0F, 0x10, 0x8B, 0x00, 0x00, 0x00, 0x00};
                    found = reader.FindPatternEx(pattern5, "xxxx????", moduleBase, GameOffsets::PATTERN_SEARCH_SIZE);
                    printf("[*] Pattern 5 (F3 0F 10 8B ????????): %s\n", found ? "FOUND [OK]" : "NOT FOUND");
                    if (found) printf("    Found at: 0x%llX\n", found);
                }

                if (!found)
                {
                    printf("[!] NO SSE PATTERNS FOUND - Trying alternative patterns...\n");

                    // Try MOV instructions instead of SSE
                    const unsigned char patternMov1[] = {0x8B, 0x87, 0x00, 0x00, 0x00, 0x00};
                    found = reader.FindPatternEx(patternMov1, "xx????", moduleBase, GameOffsets::PATTERN_SEARCH_SIZE);
                    printf("[*] Pattern MOV1 (8B 87 ??????): %s\n", found ? "FOUND [OK]" : "NOT FOUND");
                    if (found) printf("    Found at: 0x%llX\n", found);
                }

